composite.fragment:
varying vec2 vUv;

uniform sampler2D blurTexture1;
uniform sampler2D blurTexture2;
uniform sampler2D blurTexture3;
uniform sampler2D blurTexture4;
uniform sampler2D blurTexture5;
uniform float bloomStrength;
uniform float bloomRadius;
uniform float bloomFactors[NUM_MIPS];
uniform vec3 bloomTintColors[NUM_MIPS];

float lerpBloomFactor( const in float factor ) {

	float mirrorFactor = 1.2 - factor;
	return mix( factor, mirrorFactor, bloomRadius );

}

void main() {

	// 3.0 for backwards compatibility with previous alpha-based intensity
	vec3 bloom = 3.0 * bloomStrength * (
		lerpBloomFactor( bloomFactors[ 0 ] ) * bloomTintColors[ 0 ] * texture2D( blurTexture1, vUv ).rgb +
		lerpBloomFactor( bloomFactors[ 1 ] ) * bloomTintColors[ 1 ] * texture2D( blurTexture2, vUv ).rgb +
		lerpBloomFactor( bloomFactors[ 2 ] ) * bloomTintColors[ 2 ] * texture2D( blurTexture3, vUv ).rgb +
		lerpBloomFactor( bloomFactors[ 3 ] ) * bloomTintColors[ 3 ] * texture2D( blurTexture4, vUv ).rgb +
		lerpBloomFactor( bloomFactors[ 4 ] ) * bloomTintColors[ 4 ] * texture2D( blurTexture5, vUv ).rgb
	);

	float bloomAlpha = max( bloom.r, max( bloom.g, bloom.b ) );
	gl_FragColor = vec4( bloom, bloomAlpha );

}

guard.fragment:
uniform sampler2D tDiffuse; uniform vec2 uTexel; varying vec2 vUv;
vec3 safe(vec3 c) { return (any(isnan(c)) || any(isinf(c))) ? vec3(0.0) : min(c, vec3(8.0)); }
float lum(vec3 c) { return dot(c, vec3(0.2126, 0.7152, 0.0722)); }
void main() {
  vec4 raw = texture2D(tDiffuse, vUv);
  vec3 c = safe(raw.rgb);
  vec3 a = safe(texture2D(tDiffuse, vUv + vec2(uTexel.x, 0.0)).rgb), b = safe(texture2D(tDiffuse, vUv - vec2(uTexel.x, 0.0)).rgb);
  vec3 d = safe(texture2D(tDiffuse, vUv + vec2(0.0, uTexel.y)).rgb), e = safe(texture2D(tDiffuse, vUv - vec2(0.0, uTexel.y)).rgb);
  float near = max(max(lum(a), lum(b)), max(lum(d), lum(e)));
  bool bad = any(isnan(raw.rgb)) || any(isinf(raw.rgb)) || (lum(c) > 0.6 && lum(c) > near * 2.5);
  float al = (isnan(raw.a) || isinf(raw.a)) ? 0.0 : clamp(raw.a, 0.0, 1.0);
  gl_FragColor = vec4(bad ? (a + b + d + e) * 0.25 : c, al);
}
